const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',pengajuan:'M8 3h8v4H8z M6 5H4v16h16V5h-2 M8 12h8 M8 16h5',stok:'M3 7l9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10',pengembalian:'M8 7H3V2 M3 7a9 9 0 1 1-1 8 M12 7v6l4 2',laporan:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',grafik:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16V9',profil:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 8 0 0 1 16 0v3',setting:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 4v16 M4 12h16',logout:'M10 4H4v16h6 M9 12h12 M16 7l5 5-5 5',bell:'M5 16h14l-2-4V8a5 5 0 0 0-10 0v4z M10 20h4',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',menu:'M3 6h18 M3 12h18 M3 18h18'};
const icon=(n,s=18)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.stok}"/></svg>`;
const logo=()=>`<a href="#home" class="logo" aria-label="Medira — beranda"><svg class="brand-emblem" width="43" height="43" viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="1" y="1" width="46" height="46" rx="15" fill="currentColor" fill-opacity=".055" stroke="currentColor" stroke-opacity=".15"/><path d="M10 33V16.5c0-4 4.5-6 7.4-3.1L24 20l6.6-6.6c2.9-2.9 7.4-.9 7.4 3.1V33h-6V19.5l-8 8-8-8V33z" fill="currentColor"/><path d="m24 29 4 4-4 4-4-4z" fill="#B59A6B"/></svg><span class="brand-word">medira<span class="brand-caption">MEDICAL ASSET MANAGEMENT</span></span></a>`;
function device(){return `<svg viewBox="0 0 250 180" fill="none" aria-label="Ilustrasi patient monitor"><ellipse cx="125" cy="164" rx="77" ry="8" fill="#dfe6f0"/><path d="M115 121v29l-28 9h78l-28-9v-29" fill="#c9d3e1" stroke="#a6b5ca"/><rect x="37" y="20" width="176" height="109" rx="10" fill="#fdfefe" stroke="#b8c5d7" stroke-width="2"/><rect x="47" y="30" width="140" height="85" rx="4" fill="#1c3047"/><path d="M53 59h22l4-8 5 23 6-36 7 24 5-3h25 M53 90h14l7-7 7 13 7-8h39" stroke="#65cfab" stroke-width="2"/><text x="141" y="63" fill="#65cfab" font-size="23" font-family="Arial">72</text><text x="141" y="94" fill="#8cb5e7" font-size="18" font-family="Arial">98</text><circle cx="199" cy="100" r="6" fill="#dce5f1"/><path d="M195 44h8 M195 53h8 M195 62h8" stroke="#a3b2c8" stroke-width="2"/></svg>`}
function equipmentArt(i){if(i===0)return device();let common='fill="none" stroke="#8595b1" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"';let drawings=[``, `<rect x="45" y="30" width="44" height="53" rx="5" fill="#fff"/><rect x="53" y="38" width="28" height="17" rx="2" fill="#2c4263"/><path d="M55 65h7m8 0h8 M67 85v31 M44 120h46 M102 15v105 M91 20h22 M110 21v27q0 14-22 14"/><circle cx="45" cy="124" r="3"/><circle cx="89" cy="124" r="3"/>`, `<circle cx="59" cy="98" r="27" fill="#edf1f9"/><circle cx="59" cy="98" r="20"/><path d="M45 37h12v49h38l15 29h10 M58 76h34 M45 37V26H33 M89 76V58H68"/><circle cx="112" cy="120" r="7"/><path d="M57 42h27v30H57" fill="#54749a"/>`, `<rect x="42" y="36" width="65" height="80" rx="10" fill="#fff"/><rect x="51" y="47" width="46" height="19" rx="3" fill="#b5c8dd"/><path d="M57 83h35 M57 91h35 M57 99h35 M62 36v-8h27v8 M107 55q24-30 16-35"/><circle cx="55" cy="120" r="4"/><circle cx="96" cy="120" r="4"/>`, `<path d="M39 64q4-12 16-12h43q10 2 12 12l9 39H30z" fill="#fff"/><rect x="53" y="62" width="45" height="23" rx="3" fill="#c2d5da"/><path d="M65 72h18 M75 66v12 M37 90q-28-25-14-45"/><rect x="9" y="25" width="28" height="25" rx="6" fill="#758aa6"/><circle cx="77" cy="94" r="3"/>`, `<rect x="32" y="76" width="70" height="34" rx="12" fill="#fff"/><circle cx="48" cy="92" r="5"/><path d="M65 88h22 M65 95h22 M100 86q30-2 15-35 M105 49h21l-4-23h-13z" fill="#d6e3ef"/><path d="M115 26V15 M107 15h16"/>`];return `<svg viewBox="0 0 150 140" ${common}><ellipse cx="76" cy="128" rx="48" ry="5" fill="#c8d2e2" stroke="none"/>${drawings[i%6]}</svg>`}
function home(){let items=state.catalogue; let total=items.reduce((s,x)=>s+Number(x.total),0),free=items.reduce((s,x)=>s+Number(x.available),0);return `<div class="public-nav-area"><header class="public-nav">${logo()}<nav><a href="#home" style="color:var(--blue)">Beranda</a><a href="#tentang">Tentang sistem</a><a href="#katalog">Alat medis</a><a href="#alur">Alur peminjaman</a><a class="btn" href="#login">${icon('pengajuan',15)} Masuk ke sistem</a></nav></header></div><div class="home-top"><img class="hero-photo" src="assets/medical-hero.png" alt="Petugas memeriksa peralatan medis di rumah sakit"><section class="medical-hero"><span class="hero-label">${icon('stok',17)} Alat terkelola, pelayanan terjaga</span><h1>Peminjaman Alat Medis<br>Lebih <em>Mudah</em><br>dan Terorganisir.</h1><p>Temukan alat yang tersedia, ajukan peminjaman, dan pantau pengembaliannya dalam satu sistem yang terhubung.</p><div class="hero-actions"><a class="btn" href="#katalog">Lihat alat medis ${icon('arrow',16)}</a><a class="btn secondary" href="#login">Ajukan peminjaman ${icon('pengajuan',16)}</a></div></section></div><div class="metric-strip">${[[total,'Unit alat terdata','stok'],[free,'Unit siap dipinjam','dashboard'],[items.length,'Jenis alat medis','pengajuan'],['01','Sistem terintegrasi','laporan']].map(([n,t,i])=>`<div class="metric"><span class="metric-icon">${icon(i,24)}</span><div><b>${n}</b><small>${t}</small></div></div>`).join('')}</div><section class="home-section intro-grid" id="tentang"><div class="intro-image"><img src="assets/medical-hero.png" alt="Pemeriksaan kesiapan alat sebelum dipinjam"><div class="image-caption">${icon('pengajuan',24)}<div><b>Terpantau dari awal hingga kembali.</b><br><span class="muted small">Pencatatan yang jelas untuk setiap alat.</span></div></div></div><div><span class="section-kicker">Tentang Medira</span><h2>Pengelolaan alat medis<br>untuk pelayanan yang<br><span style="color:var(--blue)">lebih tertata.</span></h2><p>Medira membantu Petugas mengajukan alat dan Admin mengelola ketersediaan, persetujuan, serta pemeriksaan pengembalian. Setiap transaksi memiliki riwayat yang mudah ditelusuri.</p><div class="feature-icons">${[['stok','Stok<br>terpantau'],['pengajuan','Pengajuan<br>tercatat'],['pengembalian','Pengembalian<br>terverifikasi'],['laporan','Laporan<br>terpusat']].map(([i,t])=>`<div><span>${icon(i,19)}</span>${t}</div>`).join('')}</div></div></section><section class="catalog-section" id="katalog"><div class="section-heading"><div><h2>Alat medis tersedia</h2><p class="small" style="margin:7px 0 0">Ketersediaan terkini dari inventaris Medira.</p></div><a class="textlink" href="#katalog-semua">Lihat semua alat →</a></div><div class="catalog-grid">${['Patient Monitor','Infusion Pump','Kursi Roda','Konsentrator Oksigen','Tensimeter Digital','Nebulizer'].map(n=>items.find(x=>x.name===n)).filter(Boolean).map((x,i)=>`<button class="catalog-tile" onclick="location.hash='login'"><div class="equipment-art">${equipmentArt(i)}</div><div class="tile-text"><b>${esc(x.name)}</b><small>${x.available} unit tersedia</small></div></button>`).join('')}</div></section><section class="home-section steps" id="alur"><div class="steps-inner"><div><span class="section-kicker">Alur peminjaman</span><h2>Tiga langkah.<br>Semua tercatat.</h2><p class="small">Dari kebutuhan unit hingga alat kembali siap digunakan.</p></div><div><div class="step-number">01</div><h3>Ajukan kebutuhan alat</h3><p class="small">Pilih jenis alat, jumlah, serta durasi peminjaman sesuai kebutuhan unit.</p></div><div><div class="step-number">02</div><h3>Verifikasi & serah terima</h3><p class="small">Admin memilih unit, menyetujui pengajuan, lalu mencatat penyerahan alat.</p></div><div><div class="step-number">03</div><h3>Kembalikan & periksa</h3><p class="small">Catat kondisi pengembalian. Stok diperbarui setelah pemeriksaan.</p></div></div></section><section class="cta-banner"><div><h2>Siap mengelola peminjaman?</h2><p>Masuk ke ruang kerja untuk mulai mengajukan dan memantau alat medis.</p></div><a href="#login" class="btn">Masuk ke ruang kerja ${icon('arrow',16)}</a></section><footer class="footer"><span>© 2026 Medira · Sistem Peminjaman Alat Medis</span><span>Inventaris contoh untuk tugas kuliah</span></footer>`}
